#ifndef STAGE0_DATA_H
#define STAGE0_DATA_H

#include <genesis.h>

// Generated by tools/convert_stage.py from stage 0 ("CHAOS CITY").
// Terrain values match the original TERRAIN_TYPES (defines.h:285).

#define STAGE0_MAP_COUNT 3
#define STAGE0_MAP_W 200
#define STAGE0_MAP_H 14
#define STAGE0_TILE 16
#define STAGE0_PIXEL_W (STAGE0_MAP_W * STAGE0_TILE)
#define STAGE0_PIXEL_H (STAGE0_MAP_H * STAGE0_TILE)

#define TERRAIN_UNBLOCKED 0
#define TERRAIN_SOLID     1
#define TERRAIN_STAIR     2
#define TERRAIN_EASYBLOCK 12
#define TERRAIN_HARDBLOCK 13

// Terrain that blocks movement (matches character.cpp:1940 on normal
// difficulty: unblocked/water/scroll-lock/checkpoint/stair and the
// easy/hard mode blocks all pass through).
#define TERRAIN_BLOCKS(t) ((t) != TERRAIN_UNBLOCKED && \
                           (t) != TERRAIN_STAIR && \
                           (t) != TERRAIN_EASYBLOCK && \
                           (t) != TERRAIN_HARDBLOCK)

typedef struct { u8 map_from, tile_x, tile_y; u8 map_to, dst_x, dst_y; } StageLink;

typedef struct { u8 present; s16 adjust_y; s8 speed; } StageBgInfo;

extern const u8 stage0_terrain[STAGE0_MAP_COUNT][STAGE0_MAP_W * STAGE0_MAP_H];
extern const StageLink stage0_links[2];
extern const StageBgInfo stage0_bg_info[STAGE0_MAP_COUNT];
#define STAGE0_LINK_COUNT 2

// Full-wall columns: every one of the 15 PC data rows is
// SOLID/DOOR/SPIKE/ICE/SCROLL_LOCK (PC classmap.cpp:184-193).
// The camera edge may never sit on one (PC changeScrolling
// classmap.cpp:459/475): the view never shows what is behind a
// map divider.
#define STAGE0_SCROLL_LOCK_MAX 5
extern const u8 stage0_scroll_lock_n[STAGE0_MAP_COUNT];
extern const u8 stage0_scroll_lock[STAGE0_MAP_COUNT][STAGE0_SCROLL_LOCK_MAX];

u16 stage_terrain_at(u8 map, s16 tileX, s16 tileY);

// ---- animated tiles + tile3 (above-player layer) ----
// tile3 cells get TILE_ATTR_PRIORITY via the SGDK map patch
// callback (stage.c) so the VDP draws them over sprites.
// Anim cells point at a fixed VRAM slot (one per animation,
// 6 frames x 4 tiles); frame changes DMA 32 bytes per slot.
#define TILE_ANIM_BASE 912
#define TILE_ANIM_STRIDE 24
#define STAGE0_ANIM_SLOT_COUNT 1
#define STAGE0_ANIM_CELL_MAX 20

typedef struct { u8 x, y, slot, tile3; } StageAnimCell;
typedef struct { u8 frames; u16 delay[6]; } StageAnimSlot; // delay in frames

extern const u8 stage0_tile3_mask[STAGE0_MAP_COUNT][(STAGE0_MAP_W * STAGE0_MAP_H + 7) / 8];
extern const u8 stage0_anim_mask[STAGE0_MAP_COUNT][(STAGE0_MAP_W * STAGE0_MAP_H + 7) / 8];
extern const StageAnimCell stage0_anim_cells[STAGE0_MAP_COUNT][STAGE0_ANIM_CELL_MAX];
extern const u16 stage0_anim_cell_n[STAGE0_MAP_COUNT];
extern const StageAnimSlot stage0_anim_slots[STAGE0_ANIM_SLOT_COUNT];
extern const u16 stage0_anim_frames[STAGE0_ANIM_SLOT_COUNT][6][64];
#endif
